import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh } = ctx.THREE;

  // Root container (adapter will set position/rotation/scale)
  const root = new Group();

  // --------- Textured Plane ----------
  const planeWidth = 7; // generic size, fits hub frame
  const planeHeight = 6;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({ transparent: true });

  // Load texture if URL provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
      // Ensure texture gets disposed on cleanup
      cleanupResources.texture = tex;
    });
  }

  const planeMesh = new Mesh(geometry, material);
  // Slightly raise the plane so text can sit just above it
  planeMesh.position.set(0, 0, 0.001);
  root.add(planeMesh);

  // --------- Text Content ----------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const colors = config.visual?.colors ??
    config.intent?.visualSpec?.colors ??
    {};

  const textColor = colors.paper || '#e8ecf2';

  const textObjects = [];

  for (const item of items) {
    const txt = item?.text ?? item?.content ?? '';
    const opts = {
      fontSize: item?.typography?.fontSize ?? 96,
      color: textColor,
      align: 'center',
    };
    const textObj = ctx.fontAtlas.createText(txt, opts);
    // Position headline near top of the plane
    textObj.position.set(0, 1.5, 0.01);
    root.add(textObj);
    textObjects.push(textObj);
  }

  // --------- Cleanup ----------
  const cleanupResources = {
    texture: null,
    timelines: [],
    primitives: [],
  };

  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    if (cleanupResources.texture) cleanupResources.texture.dispose();

    // Kill any GSAP timelines (none in this node but safe)
    cleanupResources.timelines.forEach((t) => t.kill && t.kill());

    // Cleanup primitives if any were added later
    cleanupResources.primitives.forEach((p) => p.cleanup && p.cleanup());
  };

  // Empty handlers placeholder (no interactions defined)
  root.userData.handlers = {};

  return root;
}
